import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

results = []
for c in range(1, 11):
    for d in range(1, 11):
        # Check condition: c^2 - 6cd + d^2 is a perfect square
        X = c**2 - 6*c*d + d**2

        if is_perfect_square(X):
            # Calculate f(c, d) = (c^2 + d^2) / (cd)
            f_cd = (c**2 + d**2) / (c*d)

            # Store result
            results.append({
                'c': c,
                'd': d,
                'X': X,
                'f_cd': f_cd
            })

# Format results for notes.md
note_text = "Systematic Test Results (max(c, d) <= 10):\n"
if results:
    note_text += "Found quadruples where c^2 - 6cd + d^2 is a perfect square:\n"
    for res in results:
        note_text += f"  (c, d) = ({res['c']}, {res['d']}): Perfect Square = {res['X']} (sqrt={math.isqrt(res['X'])}). f(c, d) = {res['f_cd']:.4f}\n"
else:
    note_text += "No such pairs found in the range max(c, d) <= 10.\n"

print(note_text)
